Action: run_sql({'query': 'WITH parsed AS (\n  SELECT \n    gmap_id,\n    name,\n    address,\n    avg_rating,\n    num_of_reviews,\n    trim(split_part(address, \',\', -3)) as raw_street_line\n  FROM establishments\n  WHERE address IS NOT NULL AND address LIKE \'%UT%\'\n),\ncleaned AS (\n  SELECT \n    *,\n    -- Remove house number at the beginning (e.g. "450 State St" -> "State St", "3330 S 500 W" -> "S 500 W", "1495 S Black Ridge Dr #210" -> "S Black Ridge Dr #210")\n    regexp_replace(raw_street_line, \'^\\d+\\s+\', \'\') as street_no_num,\n    -- Remove unit/suite numbers at the end (e.g. "#210", "Ste 100", "Suite A")\n    regexp_replace(\n      regexp_replace(raw_street_line, \'^\\d+\\s+\', \'\'),\n      \'\\s+(?:#|Ste|Suite|Unit|Bldg|Apt)\\s*\\S+.*$\', \'\', \'i\'\n    ) as street_clean\n  FROM parsed\n)\nSELECT \n  street_clean,\n  count(*) as count_3_to_4,\n  count(CASE WHEN avg_rating = 3.0 THEN 1 END) as count_exact_3,\n  count(CASE WHEN round(avg_rating) = 3 THEN 1 END) as count_round_3\nFROM cleaned\nWHERE avg_rating >= 3.0 AND avg_rating < 4.0\nGROUP BY street_clean\nORDER BY count_3_to_4 DESC\nLIMIT 20'})

